-- Extend safe setting change history for customer shipping services and fees.
-- No settings values, product data, orders or existing history are changed.
DROP TRIGGER IF EXISTS audit_settings_insert;
--> statement-breakpoint
DROP TRIGGER IF EXISTS audit_settings_update;
--> statement-breakpoint
DROP TRIGGER IF EXISTS audit_settings_delete;
--> statement-breakpoint
CREATE TRIGGER IF NOT EXISTS audit_settings_insert AFTER INSERT ON settings
WHEN NEW.key NOT IN ('coa_scheduler_health_v1','checkout_recovery_health_v1')
BEGIN
 INSERT INTO change_events(id,occurred_at,recorded_at,source,actor,actor_type,action,entity_type,entity_id,summary,status,changes)
 VALUES(lower(hex(randomblob(16))),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),
 COALESCE((SELECT source FROM change_context WHERE id=1),'system'),
 COALESCE((SELECT actor FROM change_context WHERE id=1),'Unattributed database change'),
 COALESCE((SELECT actor_type FROM change_context WHERE id=1),'unknown'),
 COALESCE((SELECT action FROM change_context WHERE id=1),'setting.insert'),'setting',CAST(NEW.key AS TEXT),
 COALESCE((SELECT summary FROM change_context WHERE id=1),'Setting created' || ' (' || NEW.key || ')'),'succeeded',
 COALESCE(NULLIF((SELECT json_group_array(json_object('field',a.key,'before',a.value,'after',b.value)) FROM json_each(json_object('3-item discount (%)',NULL,'5-item discount (%)',NULL,'10-item discount (%)',NULL,'Shipping (cents)',NULL,'Free shipping threshold (cents)',NULL,'Presales enabled',NULL,'Rewards enabled',NULL,'Affiliate program enabled',NULL,'Automation enabled',NULL,'Automation starts',NULL,'Standard shipping enabled',NULL,'Expedited shipping enabled',NULL,'Overnight shipping enabled',NULL,'Free standard shipping enabled',NULL,'Standard handling (cents)',NULL,'Expedited handling (cents)',NULL,'Overnight handling (cents)',NULL,'USPS enabled',NULL,'UPS enabled',NULL,'FedEx enabled',NULL)) a JOIN json_each(json_object(
  '3-item discount (%)',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.packDiscounts.3') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.packDiscounts.3') ELSE NULL END,
  '5-item discount (%)',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.packDiscounts.5') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.packDiscounts.5') ELSE NULL END,
  '10-item discount (%)',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.packDiscounts.10') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.packDiscounts.10') ELSE NULL END,
  'Shipping (cents)',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingCents') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingCents') ELSE NULL END,
  'Free shipping threshold (cents)',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.freeShippingAt') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.freeShippingAt') ELSE NULL END,
  'Presales enabled',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.presalesEnabled') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.presalesEnabled') ELSE NULL END,
  'Rewards enabled',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.rewardsEnabled') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.rewardsEnabled') ELSE NULL END,
  'Affiliate program enabled',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.affiliateEnabled') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.affiliateEnabled') ELSE NULL END,
  'Automation enabled',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.enabled') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.enabled') ELSE NULL END,
  'Automation starts',CASE WHEN NEW.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.startsAt') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.startsAt') ELSE NULL END,
  'Standard shipping enabled',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.standardEnabled') IN ('true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.standardEnabled') ELSE NULL END,
  'Expedited shipping enabled',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.expeditedEnabled') IN ('true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.expeditedEnabled') ELSE NULL END,
  'Overnight shipping enabled',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.overnightEnabled') IN ('true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.overnightEnabled') ELSE NULL END,
  'Free standard shipping enabled',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.freeStandardEnabled') IN ('true','false') THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.freeStandardEnabled') ELSE NULL END,
  'Standard handling (cents)',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.standardHandlingCents')='integer' AND json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.standardHandlingCents') BETWEEN 0 AND 100000 THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.standardHandlingCents') ELSE NULL END,
  'Expedited handling (cents)',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.expeditedHandlingCents')='integer' AND json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.expeditedHandlingCents') BETWEEN 0 AND 100000 THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.expeditedHandlingCents') ELSE NULL END,
  'Overnight handling (cents)',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.overnightHandlingCents')='integer' AND json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.overnightHandlingCents') BETWEEN 0 AND 100000 THEN json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.overnightHandlingCents') ELSE NULL END,
  'USPS enabled',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers')='array' AND NOT EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers') WHERE type!='text' OR value NOT IN ('USPS','UPS','FedEx')) THEN EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers') WHERE value='USPS') ELSE NULL END,
  'UPS enabled',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers')='array' AND NOT EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers') WHERE type!='text' OR value NOT IN ('USPS','UPS','FedEx')) THEN EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers') WHERE value='UPS') ELSE NULL END,
  'FedEx enabled',CASE WHEN NEW.key='store' AND json_type(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers')='array' AND NOT EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers') WHERE type!='text' OR value NOT IN ('USPS','UPS','FedEx')) THEN EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(NEW.value) THEN NEW.value ELSE '{}' END,'$.shippingOptions.carriers') WHERE value='FedEx') ELSE NULL END
)) b ON a.key=b.key WHERE a.value IS NOT b.value),'[]'),'[{"field":"Other stored fields","before":"Not copied","after":"Changed; private values are not recorded"}]'));
END;
