 INSERT INTO change_events(id,occurred_at,recorded_at,source,actor,actor_type,action,entity_type,entity_id,summary,status,changes)
 VALUES(lower(hex(randomblob(16))),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),
 COALESCE((SELECT source FROM change_context WHERE id=1),'system'),
 COALESCE((SELECT actor FROM change_context WHERE id=1),'Unattributed database change'),
 COALESCE((SELECT actor_type FROM change_context WHERE id=1),'unknown'),
 COALESCE((SELECT action FROM change_context WHERE id=1),'setting.delete'),'setting',CAST(OLD.key AS TEXT),
 COALESCE((SELECT summary FROM change_context WHERE id=1),'Setting removed' || ' (' || OLD.key || ')'),'succeeded',
 COALESCE(NULLIF((SELECT json_group_array(json_object('field',a.key,'before',a.value,'after',b.value)) FROM json_each(json_object(
  '3-item discount (%)',CASE WHEN OLD.key IN ('store','coa_delivery_v1','checkout_recovery_v1') AND json_type(CASE WHEN json_valid(OLD.value) THEN OLD.value ELSE '{}' END,'$.packDiscounts.3') IN ('integer','real','true','false') THEN json_extract(CASE WHEN json_valid(OLD.value) THEN OLD.value ELSE '{}' END,'$.packDiscounts.3') ELSE NULL END,
